(() => {
// Section 4 teaching model. Opcode meanings follow the 2027–2029 Cambridge 9618 syllabus.
// One source line occupies one address; arithmetic is unbounded except the declared 8-bit bit labs.
const INSTRUCTIONS = Object.freeze({
  LDM:{group:'Data movement',operand:'immediate',effect:'Load the number into ACC'},
  LDD:{group:'Data movement',operand:'direct',effect:'Load memory contents into ACC'},
  LDI:{group:'Data movement',operand:'indirect',effect:'Follow a pointer, then load into ACC'},
  LDX:{group:'Data movement',operand:'indexed',effect:'Load memory at address plus IX into ACC'},
  LDR:{group:'Data movement',operand:'immediate',effect:'Load the number into IX'},
  MOV:{group:'Data movement',operand:'register',effect:'Copy ACC into IX'},
  STO:{group:'Data movement',operand:'direct',effect:'Store ACC at the address'},
  ADD:{group:'Arithmetic',operand:'value',effect:'Add the operand to ACC'},
  SUB:{group:'Arithmetic',operand:'value',effect:'Subtract the operand from ACC'},
  INC:{group:'Arithmetic',operand:'register',effect:'Add one to ACC or IX'},
  DEC:{group:'Arithmetic',operand:'register',effect:'Subtract one from ACC or IX'},
  JMP:{group:'Control flow',operand:'address',effect:'Set PC to the address'},
  CMP:{group:'Comparison',operand:'value',effect:'Compare ACC for equality with the operand'},
  CMI:{group:'Comparison',operand:'indirect',effect:'Compare ACC with the value through a pointer'},
  JPE:{group:'Control flow',operand:'address',effect:'Jump when the previous comparison was True'},
  JPN:{group:'Control flow',operand:'address',effect:'Jump when the previous comparison was False'},
  IN:{group:'Input/output',operand:'none',effect:'Read one character ASCII code into ACC'},
  OUT:{group:'Input/output',operand:'none',effect:'Output the character whose ASCII code is in ACC'},
  END:{group:'Control flow',operand:'none',effect:'Return control to the operating system'},
  AND:{group:'Bit manipulation',operand:'value',effect:'Bitwise AND with ACC'},
  OR:{group:'Bit manipulation',operand:'value',effect:'Bitwise OR with ACC'},
  XOR:{group:'Bit manipulation',operand:'value',effect:'Bitwise XOR with ACC'},
  LSL:{group:'Bit manipulation',operand:'immediate',effect:'Logical shift ACC left'},
  LSR:{group:'Bit manipulation',operand:'immediate',effect:'Logical shift ACC right'},
});

function numberFromToken(token) {
  const value=String(token).trim();
  if (/^#[+-]?\d+$/.test(value)) return Number(value.slice(1));
  if (/^B[01]+$/i.test(value)) return parseInt(value.slice(1),2);
  if (/^&[0-9a-f]+$/i.test(value)) return parseInt(value.slice(1),16);
  if (/^[+-]?\d+$/.test(value)) return Number(value);
  throw new Error(`Invalid number: ${value}`);
}

function assemble(lines, origin=0) {
  if (!Number.isSafeInteger(origin) || origin<0) throw new Error('Origin must be a non-negative integer.');
  const symbols={}; const source=[]; const errors=[];
  lines.forEach((raw,index)=>{
    const text=String(raw).trim();
    if (!text) return;
    const match=text.match(/^(?:([A-Z][A-Z0-9_]*):\s*)?(.*)$/i);
    if (!match || !match[2]) {errors.push(`Line ${index+1}: missing instruction or data.`);return;}
    const address=origin+source.length;
    const label=match[1]?.toUpperCase();
    if (label) {if (Object.hasOwn(symbols,label)) errors.push(`Line ${index+1}: duplicate label ${label}.`); else symbols[label]=address;}
    source.push({address,label,text:match[2].trim(),line:index+1});
  });
  const memory={}; const resolved=[];
  for (const item of source) {
    const parts=item.text.match(/^([A-Z]+)(?:\s+(.+))?$/i);
    if (!parts) {try {memory[item.address]=numberFromToken(item.text);resolved.push({...item,kind:'data',value:memory[item.address]});} catch {errors.push(`Line ${item.line}: invalid data or instruction.`);} continue;}
    const op=parts[1].toUpperCase(), operand=parts[2]?.trim();
    if (!INSTRUCTIONS[op]) {
      try {memory[item.address]=numberFromToken(item.text);resolved.push({...item,kind:'data',value:memory[item.address]});}
      catch {errors.push(`Line ${item.line}: unknown instruction ${op}.`);}
      continue;
    }
    const needs=INSTRUCTIONS[op].operand!=='none';
    if (needs!==Boolean(operand)) {errors.push(`Line ${item.line}: ${op} ${needs?'requires':'does not take'} an operand.`);continue;}
    if (operand && ['LDM','LDR'].includes(op) && !/^#[+-]?\d+$/.test(operand)) {errors.push(`Line ${item.line}: ${op} requires #n immediate notation.`);continue;}
    if (operand && ['LSL','LSR'].includes(op) && !/^#[+]?(?:0|[1-9]\d*)$/.test(operand)) {errors.push(`Line ${item.line}: ${op} requires a non-negative #n shift amount.`);continue;}
    if (operand && ['LDD','LDI','LDX','STO','JMP','CMI','JPE','JPN'].includes(op) && /^(?:#[+-]?\d+|B[01]+|&[0-9A-F]+)$/i.test(operand)) {errors.push(`Line ${item.line}: ${op} requires an address, not an immediate value.`);continue;}
    let value=null;
    if (operand) {
      const key=operand.toUpperCase();
      if (Object.hasOwn(symbols,key)) value=symbols[key];
      else if (/^[A-Z][A-Z0-9_]*$/i.test(operand) && !/^B[01]+$/i.test(operand) && !['ACC','IX'].includes(key)) {errors.push(`Line ${item.line}: undefined label ${operand}.`);continue;}
      else if (['ACC','IX'].includes(key)) value=key;
      else {try {value=numberFromToken(operand);} catch {errors.push(`Line ${item.line}: invalid operand ${operand}.`);continue;}}
      if (INSTRUCTIONS[op].operand==='register' && value!=='IX' && !(op==='INC'||op==='DEC') ) {errors.push(`Line ${item.line}: MOV requires IX.`);continue;}
      if (INSTRUCTIONS[op].operand==='register' && !['ACC','IX'].includes(value)) {errors.push(`Line ${item.line}: register must be ACC or IX.`);continue;}
    }
    const instruction={op,operand,operandValue:value,address:item.address};
    memory[item.address]=instruction;
    resolved.push({...item,kind:'instruction',instruction,resolved:`${op}${operand?` ${typeof value==='number' && Object.hasOwn(symbols,operand.toUpperCase())?value:operand}`:''}`});
  }
  return {symbols,source,resolved,memory,errors};
}

function initialState(program) {
  const built=assemble(program.lines,program.origin??0);
  if (built.errors.length) throw new Error(built.errors.join(' '));
  return {pc:program.origin??0,acc:program.acc??0,ix:program.ix??0,mar:null,mdr:null,cir:null,comparison:null,
    memory:{...(program.memory??{}),...built.memory},input:program.input??'',inputCursor:0,output:'',halted:false,trace:[],lastDiff:[],symbols:built.symbols};
}

function cell(memory,address) {
  if (!Number.isSafeInteger(address)||address<0||!Object.hasOwn(memory,address)) throw new Error(`Memory address ${address} does not exist in this scenario.`);
  return memory[address];
}
function data(memory,address) {
  const value=cell(memory,address);
  if (typeof value!=='number') throw new Error(`Memory[${address}] holds an instruction, not numeric data.`);
  return value;
}
function resolveAddress(mode, operand, memory, ix=0, pcBase=0) {
  const n=numberFromToken(operand);
  if (mode==='immediate') return {path:[`literal ${n}`],value:n,address:null};
  if (mode==='relative') return {path:[`PC base ${pcBase}`,`offset ${n}`,`address ${pcBase+n}`],address:pcBase+n,value:null};
  const address=mode==='indexed'?n+ix:mode==='indirect'?data(memory,n):n;
  if (!['direct','indirect','indexed'].includes(mode)) throw new Error(`Unknown addressing mode: ${mode}.`);
  const value=data(memory,address);
  return {path:mode==='indirect'?[`Memory[${n}] → ${address}`,`Memory[${address}] → ${value}`]:mode==='indexed'?[`${n} + IX ${ix} → ${address}`,`Memory[${address}] → ${value}`]:[`Memory[${address}] → ${value}`],address,value};
}
function operandValue(state,instruction,indirect=false) {
  const token=instruction.operand;
  if (indirect) {
    const pointer=data(state.memory,instruction.operandValue);
    state.mar=pointer; state.mdr=data(state.memory,pointer);return state.mdr;
  }
  if (/^(?:#[+-]?\d+|B[01]+|&[0-9A-F]+)$/i.test(token)) return numberFromToken(token);
  state.mar=instruction.operandValue;state.mdr=data(state.memory,state.mar);return state.mdr;
}
function stateDiff(before,after) {
  const keys=['pc','acc','ix','mar','mdr','cir','comparison','output','halted'];
  const changes=keys.filter(key=>JSON.stringify(before[key])!==JSON.stringify(after[key])).map(key=>`${key.toUpperCase()}: ${before[key]??'—'} → ${after[key]??'—'}`);
  for (const [address,value] of Object.entries(after.memory)) if (JSON.stringify(before.memory[address])!==JSON.stringify(value)) changes.push(`Memory[${address}]: ${before.memory[address]??'—'} → ${value}`);
  return changes;
}
function stepInstruction(current) {
  if (current.halted) return current;
  const state={...current,memory:{...current.memory},trace:[...current.trace]};
  const address=state.pc;
  const instruction=cell(state.memory,address);
  if (!instruction || typeof instruction!=='object'||!instruction.op) throw new Error(`Memory[${address}] is data, not an instruction.`);
  const {op,operandValue:value}=instruction;
  state.mar=address;state.mdr=instruction.text??`${op}${instruction.operand?` ${instruction.operand}`:''}`;state.cir=state.mdr;state.pc=address+1;
  switch(op) {
    case 'LDM':state.acc=value;break;
    case 'LDR':state.ix=value;break;
    case 'LDD':state.mar=value;state.mdr=data(state.memory,value);state.acc=state.mdr;break;
    case 'LDI':state.acc=operandValue(state,instruction,true);break;
    case 'LDX':state.mar=value+state.ix;state.mdr=data(state.memory,state.mar);state.acc=state.mdr;break;
    case 'MOV':state.ix=state.acc;break;
    case 'STO':if(!Number.isSafeInteger(value)||value<0)throw new Error('Store address must be a non-negative integer.');state.mar=value;state.mdr=state.acc;state.memory[value]=state.acc;break;
    case 'ADD':state.acc+=operandValue(state,instruction);break;
    case 'SUB':state.acc-=operandValue(state,instruction);break;
    case 'INC':state[value.toLowerCase()]++;break;
    case 'DEC':state[value.toLowerCase()]--;break;
    case 'CMP':state.comparison=state.acc===operandValue(state,instruction);break;
    case 'CMI':state.comparison=state.acc===operandValue(state,instruction,true);break;
    case 'JMP':state.pc=value;break;
    case 'JPE':if(state.comparison===true)state.pc=value;break;
    case 'JPN':if(state.comparison===false)state.pc=value;break;
    case 'IN':{
      const character=state.input[state.inputCursor];if(!character)throw new Error('No input character is available.');
      state.acc=character.charCodeAt(0);state.inputCursor++;break;
    }
    case 'OUT':{
      if(!Number.isInteger(state.acc)||state.acc<0||state.acc>127)throw new Error('ACC is not a valid ASCII character code (0–127).');
      state.output+=String.fromCharCode(state.acc);break;
    }
    case 'AND':state.acc=(state.acc&operandValue(state,instruction))&255;break;
    case 'OR':state.acc=(state.acc|operandValue(state,instruction))&255;break;
    case 'XOR':state.acc=(state.acc^operandValue(state,instruction))&255;break;
    case 'LSL':state.acc=shiftBits(state.acc,'logical','left',value).value;break;
    case 'LSR':state.acc=shiftBits(state.acc,'logical','right',value).value;break;
    case 'END':state.halted=true;state.pc=null;break;
    default:throw new Error(`Unsupported instruction: ${op}.`);
  }
  state.lastDiff=stateDiff(current,state);
  state.trace.push({address,instruction:state.cir,acc:state.acc,ix:state.ix,nextPC:state.pc,comparison:state.comparison,output:state.output,diff:state.lastDiff});
  return state;
}
function fetchMicrosteps(current) {
  const instruction=cell(current.memory,current.pc);
  if(typeof instruction!=='object')throw new Error(`Memory[${current.pc}] is not an instruction.`);
  const text=`${instruction.op}${instruction.operand?` ${instruction.operand}`:''}`;
  return [
    {operation:'MAR ← [PC]',change:`MAR: ${current.mar??'—'} → ${current.pc}`,bus:'Address: CPU → memory',active:'MAR',value:current.pc},
    {operation:'READ',change:`Memory[${current.pc}] selected`,bus:'Control: READ → memory',active:'Memory',value:current.pc},
    {operation:'MDR ← [[MAR]]',change:`MDR: ${current.mdr??'—'} → ${text}`,bus:'Data: memory → CPU',active:'MDR',value:text},
    {operation:'CIR ← [MDR]',change:`CIR: ${current.cir??'—'} → ${text}`,bus:'Internal transfer',active:'CIR',value:text},
    {operation:'PC ← [PC] + 1',change:`PC: ${current.pc} → ${current.pc+1}`,bus:'Internal transfer',active:'PC',value:current.pc+1},
    {operation:'DECODE',change:`CU decodes ${instruction.op}; execute behaviour depends on the opcode.`,bus:'Control signals',active:'CU',value:instruction.op},
  ];
}
function shiftBits(value,kind,direction,amount,width=8) {
  if(!Number.isInteger(width)||width<2||width>30||!Number.isInteger(value)||value<0||value>=2**width)throw new Error(`Enter an unsigned ${width}-bit value.`);
  if(!Number.isInteger(amount)||amount<0||amount>width)throw new Error(`Shift amount must be 0–${width}.`);
  if(!['logical','arithmetic','cyclic'].includes(kind)||!['left','right'].includes(direction))throw new Error('Choose a valid shift type and direction.');
  const mask=2**width-1;let result=value;
  const states=[result];
  for(let i=0;i<amount;i++) {
    if(kind==='cyclic')result=direction==='left'?((result<<1)|(result>>(width-1)))&mask:((result>>1)|((result&1)<<(width-1)))&mask;
    else if(direction==='left')result=(result<<1)&mask;
    else result=kind==='arithmetic'?((result>>1)|(result&(1<<(width-1))))&mask:result>>1;
    states.push(result);
  }
  return {value:result,states};
}
function applyMask(value,mask,operation,width=8) {
  const limit=2**width;
  if(![value,mask].every(n=>Number.isInteger(n)&&n>=0&&n<limit))throw new Error(`Both values must fit in ${width} bits.`);
  if(operation==='AND')return value&mask;
  if(operation==='OR')return value|mask;
  if(operation==='XOR')return value^mask;
  throw new Error('Choose AND, OR or XOR.');
}
const bits=(value,width=8)=>Number(value).toString(2).padStart(width,'0');


const root=document.querySelector('.s4-lesson');
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const button=(label,action,primary=false)=>`<button type="button" data-action="${action}"${primary?' class="s4-primary"':''}>${label}</button>`;
const control=buttons=>`<div class="s4-activity-controls">${buttons.join('')}</div>`;
const status=message=>`<p class="s4-status" role="status" aria-live="polite">${escapeHtml(message)}</p>`;
const panel=(title,body)=>`<section class="s4-panel"><h5>${escapeHtml(title)}</h5>${body}</section>`;
const memoryHtml=(memory,current=null,onClick=false,changed=null)=>`<div class="s4-memory-list">${Object.entries(memory).sort((a,b)=>Number(a[0])-Number(b[0])).map(([address,value])=>`<div class="s4-memory-row${Number(address)===changed?' changed':''}" data-current="${Number(address)===current}">${onClick?`<button type="button" data-cell="${address}">${String(address).padStart(3,'0')}</button>`:`<span>${String(address).padStart(3,'0')}</span>`}<span>${escapeHtml(typeof value==='object'?`${value.op}${value.operand?` ${value.operand}`:''}`:value)}</span></div>`).join('')}</div>`;
const registers=(state,changed=[])=>`<div class="s4-reg-grid">${[['PC',state.pc],['MAR',state.mar],['MDR',state.mdr],['CIR',state.cir],['ACC',state.acc],['IX',state.ix],['Status',state.comparison]].map(([name,value])=>`<div class="s4-reg${changed.includes(name.toLowerCase())?' changed':''}"><strong>${name}</strong><span>${escapeHtml(value===null?'—':value)}</span></div>`).join('')}</div>`;
const binStrip=(value,prior=null)=>`<div class="s4-bit-strip" aria-label="8 bit value ${bits(value)}">${bits(value).split('').map((bit,index)=>`<span${prior!==null && bits(prior)[index]!==bit?' class="changed"':''}>${bit}</span>`).join('')}</div>`;
const error=(el,message)=>{const target=el.querySelector('[role=status]');if(target){target.textContent=message;target.classList.add('s4-error');}};
const clearError=el=>el.querySelector('[role=status]')?.classList.remove('s4-error');

function mount(el,render,reset){render();el.addEventListener('s4-reset',()=>{reset();render();});}
function stored(el){
  let variant='A',selected=0,state;
  const make=()=>initialState({origin:0,acc:0,ix:0,lines:['LDD 20',`${variant==='A'?'ADD':'SUB'} 21`,'STO 22','END'],memory:{20:18,21:24,22:0}});
  const reset=()=>{state=make();selected=0;};reset();
  const render=()=>{el.innerHTML=`<h4>Stored Program Explorer</h4>${control([button('Load Program A · add','a',true),button('Load Program B · subtract','b'),button('Step instruction','step'),button('Reset','reset')])}<div class="s4-activity-grid">${panel('Same processor · CU + ALU',registers(state,state.lastDiff.map(x=>x.split(':')[0].toLowerCase())))}${panel('One IAS · instruction and data cells',memoryHtml(state.memory,state.pc,true))}</div>${status(state.halted?`Program ${variant} finished: Memory[22]=${state.memory[22]}.`:state.trace.length?state.lastDiff.join(' · '):'The CPU hardware stays the same. Click an IAS cell to inspect its role.')}`;};
  el.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;const cell=event.target.closest('[data-cell]')?.dataset.cell;
    if(cell!==undefined){selected=Number(cell);const value=state.memory[selected];const message=typeof value==='object'?`Address ${selected} holds an instruction (${value.op}). Fetching it makes the CU decode it.`:`Address ${selected} holds data value ${value}. An instruction can read or write it.`;el.querySelector('[role=status]').textContent=message;return;}
    if(action==='a'||action==='b'){variant=action.toUpperCase();reset();render();}
    if(action==='reset'){reset();render();}
    if(action==='step'){try{state=stepInstruction(state);render();}catch(e){error(el,e.message);}}
  });mount(el,render,reset);
}
function components(el){let index=0;let result=18;const stages=[['CIR','ADD 5 is retained as the current instruction.'],['CU','CU decodes ADD and coordinates a read of Memory[5].'],['IAS','Memory[5] supplies 24 through the transfer path.'],['ALU','ALU combines ACC 18 and the operand 24.'],['ACC','ACC receives the calculated result 42.']];
 const render=()=>{const stage=stages[Math.min(index,4)];el.innerHTML=`<h4>One ADD instruction</h4><p>Initial ACC=18 · Memory[5]=24. Each step has timing; one clock pulse is not an entire instruction.</p>${control([button('Previous','previous'),button('Next step','next',true),button('Reset','reset')])}<div class="s4-activity-grid">${panel('CPU',`<div class="s4-reg-grid">${['CIR','CU','ALU','ACC','Clock'].map(x=>`<div class="s4-reg${x===stage[0]?' changed':''}"><strong>${x}</strong><span>${x==='ACC'?result:x==='Clock'?'timing':x==='CIR'?'ADD 5':'ready'}</span></div>`).join('')}</div>`)}${panel('IAS',memoryHtml({5:24},5))}</div>${status(stage[1])}`;};
 el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='next'){index=Math.min(4,index+1);if(index===4)result=42;render();}if(a==='previous'){index=Math.max(0,index-1);result=index===4?42:18;render();}if(a==='reset'){index=0;result=18;render();}});mount(el,render,()=>{index=0;result=18;});
}
function registersActivity(el){const make=()=>initialState({origin:40,acc:0,ix:0,lines:['LDD 600','END'],memory:{600:27}});let state=make(),micro=0,display={...state},message='Predict which register changes before stepping.';
 const reset=()=>{state=make();micro=0;display={...state};message='Predict which register changes before stepping.';};
 const render=()=>{el.innerHTML=`<h4>Register Dashboard</h4>${control([button('Step','step',true),button('Reset','reset')])}<div class="s4-activity-grid">${panel('CPU registers',registers(display,(micro===0?[]:[['mar'],[],['mdr'],['cir'],['pc'],[],['acc']][Math.min(micro-1,6)])))}${panel('IAS',memoryHtml(state.memory,display.mar))}</div>${status(message)}`;};
 el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset'){reset();render();return;}if(a!=='step')return;try{const steps=fetchMicrosteps(state);if(micro<steps.length){const x=steps[micro];display={...display};display[x.active.toLowerCase()]=x.value;message=`${x.operation} · ${x.change} · ${x.bus}`;micro++;}else if(micro===steps.length){state=stepInstruction(state);display=state;micro++;message=`EXECUTE LDD 600 · ACC: 0 → 27. MAR=600 selects the address; MDR=27 holds the value.`;}else message='Instruction complete. PC points to the next instruction while CIR still retains LDD 600.';render();}catch(e){error(el,e.message);}});mount(el,render,reset);
}
function bus(el){let memory={300:8,301:0},type='READ',step=0,address=300,value=12,message='Choose READ or WRITE and advance the ordered bus transfers.';
 const reset=()=>{memory={300:8,301:0};type='READ';step=0;address=300;value=12;message='Choose READ or WRITE and advance the ordered bus transfers.';};
 const render=()=>{const active=step?Math.min(step,3)-1:-1;const path=type==='READ'?[['Address','CPU → Memory',address],['Control','READ → Memory','read'],['Data','Memory → CPU',memory[address]]]:[['Address','CPU → Memory',address],['Data','CPU → Memory',value],['Control','WRITE → Memory','write']];el.innerHTML=`<h4>Bus Transaction Simulator</h4><label>Operation<select data-field="type"><option${type==='READ'?' selected':''}>READ</option><option${type==='WRITE'?' selected':''}>WRITE</option></select></label><label>Address<input data-field="address" type="number" min="0" value="${address}"></label><label>Write value<input data-field="value" type="number" value="${value}"></label>${control([button('Next transfer','next',true),button('Reset','reset')])}<div class="s4-activity-grid">${panel('Three bus paths',`<div class="s4-data-path">${path.map(([name,direction,data],i)=>`<div class="s4-bus-line${active===i?' active':''}"><strong>${name} bus</strong><span>${direction}</span><code>${escapeHtml(data)}</code></div>`).join('')}</div>`)}${panel('Memory',memoryHtml(memory,address,false,step===3&&type==='WRITE'?address:null))}</div>${status(message)}`;};
 el.addEventListener('change',event=>{const field=event.target.dataset.field;if(!field)return;const raw=event.target.value;if(field==='type')type=raw;else if(field==='address')address=Number(raw);else value=Number(raw);step=0;message='Transaction changed. Start with the address transfer.';render();});
 el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset'){reset();render();return;}if(a!=='next')return;if(!Number.isInteger(address)||!Object.hasOwn(memory,address)){error(el,'Use an existing memory address: 300 or 301.');return;}if(!Number.isSafeInteger(value)){error(el,'Enter an integer data value.');return;}step=Math.min(3,step+1);if(step===3&&type==='WRITE')memory[address]=value;message=step===1?`Address bus selects location ${address}; it does not carry the stored value.`:step===2?`${type==='READ'?'READ control signal goes':'Data value travels'} from CPU to memory.`:type==='READ'?`Data bus returns ${memory[address]} from Memory[${address}] to CPU.`:`WRITE control signal commits ${value} to Memory[${address}].`;render();});mount(el,render,reset);
}
function width(el){let addressBits=8,bytesPer=1,dataBits=32;const reset=()=>{addressBits=8;bytesPer=1;dataBits=32;};const render=()=>{const locations=2**addressBits;el.innerHTML=`<h4>Bus Width Lab</h4><label>Address bits · ${addressBits}<input data-field="addressBits" type="range" min="4" max="12" value="${addressBits}"></label><label>Bytes per addressable location<select data-field="bytesPer">${[1,2,4].map(n=>`<option value="${n}"${n===bytesPer?' selected':''}>${n}</option>`).join('')}</select></label><label>Data bus width<select data-field="dataBits">${[8,16,32,64].map(n=>`<option value="${n}"${n===dataBits?' selected':''}>${n} bits</option>`).join('')}</select></label><div class="s4-activity-grid">${panel('Address capacity',`<strong>2<sup>${addressBits}</sup> = ${locations} locations</strong><p>${locations} × ${bytesPer} bytes = ${locations*bytesPer} bytes in this declared model.</p>`)}${panel('Transfer width',`<strong>256 bits ÷ ${dataBits} bits = ${Math.ceil(256/dataBits)} transfers</strong><p>Each transfer carries at most ${dataBits} bits. This is a width calculation, not a performance benchmark.</p>`)}</div>`;};el.addEventListener('input',event=>{const field=event.target.dataset.field;if(!field)return;const n=Number(event.target.value);if(field==='addressBits')addressBits=n;if(field==='bytesPer')bytesPer=n;if(field==='dataBits')dataBits=n;render();});mount(el,render,reset);}
function performance(el){let workload='parallel',change='cores';const reasons={parallel:{cores:'Likely helps: independent calculations can run on separate cores.',clock:'May help each calculation, but overall work also depends on other limits.',cache:'May help only if useful values are reused.',bus:'Limited unless large transfers are restricting progress.',type:'Design differences may help; inspect the actual task.'},chain:{cores:'Limited: each calculation depends on the previous result.',clock:'May help if processor cycles limit this chain; no fixed speedup follows.',cache:'May help if repeated data access is a bottleneck.',bus:'Limited if memory transfers are not the main wait.',type:'Instruction implementation may differ; compare the actual design and task.'},reuse:{cores:'Limited for a single repeated access stream unless work is parallel.',clock:'May help, but repeated memory wait can still dominate.',cache:'Likely helps: retained copies can avoid repeated RAM access.',bus:'May have limited effect if cached data are already close to the CPU.',type:'Design differences may matter; do not infer a fixed factor.'},transfer:{cores:'May have limited effect when one transfer path is the bottleneck.',clock:'May have limited effect while transfers are waiting.',cache:'May help only if the transferred data are reused.',bus:'Likely helps per transfer when bus width is the limiting factor.',type:'A different design can affect transfer and computation behaviour.'}};
 const reset=()=>{workload='parallel';change='cores';};const render=()=>{el.innerHTML=`<h4>Performance Bottleneck Lab</h4><label>Workload<select data-field="workload">${[['parallel','Many independent calculations'],['chain','One dependent chain'],['reuse','Repeated small data set'],['transfer','Large data transfers']].map(([v,t])=>`<option value="${v}"${v===workload?' selected':''}>${t}</option>`).join('')}</select></label><label>Proposed change<select data-field="change">${[['cores','More cores'],['clock','Higher clock speed'],['cache','Larger cache'],['bus','Wider data bus'],['type','Different processor type']].map(([v,t])=>`<option value="${v}"${v===change?' selected':''}>${t}</option>`).join('')}</select></label>${status(reasons[workload][change])}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='workload')workload=event.target.value;if(event.target.dataset.field==='change')change=event.target.value;render();});mount(el,render,reset);}
function cache(el){let request=0,held=[],hits=0,misses=0;const sequence=['A','A','B','A'];const reset=()=>{request=0;held=[];hits=0;misses=0;};const render=()=>{el.innerHTML=`<h4>Cache activity · A, A, B, A</h4>${control([button('Next request','next',true),button('Reset','reset')])}<div class="s4-activity-grid">${panel('Request sequence',`<p>${sequence.map((v,i)=>`<strong${i===request-1?' class="s4-selected"':''}>${v}</strong>`).join(' → ')}</p><p>Cache retains both A and B in this model.</p>`)}${panel('State',`<p>Held: ${held.join(', ')||'empty'}</p><p>Hits: ${hits} · Misses: ${misses} · RAM accesses: ${misses}</p>`)}</div>${status(request?`${sequence[request-1]} was a ${held.includes(sequence[request-1]) && !(request===1||request===3)?'hit or retained item':'request'}. Follow the counts above.`:'Cache starts empty. A miss uses RAM → cache → CPU; a hit uses cache → CPU.')}`;};el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset'){reset();render();return;}if(a==='next'&&request<sequence.length){const item=sequence[request];const hit=held.includes(item);if(hit)hits++;else{misses++;held.push(item);}request++;render();el.querySelector('[role=status]').textContent=`Request ${request}: ${item} — cache ${hit?'hit; Cache → CPU':'miss; RAM → Cache → CPU'}.`;}});mount(el,render,reset);}
function ports(el){let need='keyboard',port='USB';const needs={keyboard:['USB','Digital peripheral data; USB can also provide power.'],flash:['USB','Digital peripheral data and power are supplied by USB.'],display:['HDMI','This display needs digital video and audio in one connection.'],projector:['VGA','This older projector accepts analogue video only; audio needs a separate path.']};const reset=()=>{need='keyboard';port='USB';};const render=()=>{const [expected,reason]=needs[need];el.innerHTML=`<h4>Connection Lab</h4><label>Device need<select data-field="need">${[['keyboard','Keyboard'],['flash','Flash drive'],['display','Display with built-in speakers'],['projector','Analogue video projector']].map(([v,t])=>`<option value="${v}"${v===need?' selected':''}>${t}</option>`).join('')}</select></label><label>Choose port<select data-field="port">${['USB','HDMI','VGA'].map(v=>`<option${v===port?' selected':''}>${v}</option>`).join('')}</select></label>${control([button('Check connection','check',true)])}${status('Select the required signal and check your connection.')}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='need')need=event.target.value;if(event.target.dataset.field==='port')port=event.target.value;render();});el.addEventListener('click',event=>{if(event.target.closest('[data-action]')?.dataset.action==='check'){const [expected,reason]=needs[need];el.querySelector('[role=status]').textContent=port===expected?`Suitable: ${reason}`:`This need is best matched to ${expected}. ${reason}`;}});mount(el,render,reset);}
function notation(el){let selected='[PC]',stage=0;const items={'PC':'The PC register itself is the destination or source named by this symbol.','[PC]':'The contents of PC are 40, the next instruction address.','MAR':'MAR is the address register that receives a value.','[MAR]':'After the transfer, MAR contains 40.','[[MAR]]':'Follow address 40 into IAS; the contents are LDD 600.','←':'Copy the value on the right into the destination on the left.'};const reset=()=>{selected='[PC]';stage=0;};const render=()=>{el.innerHTML=`<h4>Notation Explorer</h4><p><code>MAR ← [PC]</code> then <code>MDR ← [[MAR]]</code></p>${control(Object.keys(items).map((key,i)=>button(escapeHtml(key),`item${i}`)))}<div class="s4-activity-grid">${panel('Pointer path',`<p>PC contains <strong>40</strong> → MAR contains <strong>${stage?40:'—'}</strong> → Memory[40] contains <strong>LDD 600</strong> → MDR contains <strong>${stage===2?'LDD 600':'—'}</strong></p>`)}${panel('Follow one transfer',control([button('Copy PC to MAR','mar'),button('Read Memory[MAR] to MDR','mdr')]))}</div>${status(items[selected])}`;};el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(!a)return;if(a.startsWith('item'))selected=Object.keys(items)[Number(a.slice(4))];if(a==='mar')stage=1;if(a==='mdr')stage=2;render();});mount(el,render,reset);}
function fetch(el){const program={origin:0,acc:0,ix:0,lines:['LDD 4','ADD 5','STO 6','END'],memory:{4:18,5:24,6:0}};let state=initialState(program),micro=0,display={...state},timer=null,speed=700,message='Predict the next register change before each micro-step.';
 const pause=()=>{if(timer){clearInterval(timer);timer=null;}};const reset=()=>{pause();state=initialState(program);micro=0;display={...state};message='Predict the next register change before each micro-step.';};
 const next=()=>{if(state.halted){pause();return;}try{if(micro<6){const m=fetchMicrosteps(state)[micro];display={...display};if(['MAR','MDR','CIR','PC'].includes(m.active))display[m.active.toLowerCase()]=m.value;message=`${m.operation} · ${m.change} · ${m.bus}`;micro++;}else{state=stepInstruction(state);display=state;micro=0;message=`EXECUTE · ${state.lastDiff.join(' · ')}`;if(state.halted)pause();}render();}catch(e){pause();error(el,e.message);}};
 const render=()=>{el.innerHTML=`<h4>Fetch–Execute Simulator</h4>${control([button('Next micro-step','micro',true),button('Next instruction','instruction'),button(timer?'Pause':'Run',timer?'pause':'run'),button('Reset','reset')])}<label>Speed<select data-field="speed"><option value="1000"${speed===1000?' selected':''}>Slow</option><option value="700"${speed===700?' selected':''}>Normal</option><option value="350"${speed===350?' selected':''}>Fast</option></select></label><div class="s4-activity-grid">${panel('Processor Workspace',registers(display))}${panel('IAS · current access',memoryHtml(state.memory,display.mar))}</div><div class="s4-data-path"><div class="s4-bus-line${/Address/.test(message)?' active':''}">Address bus · CPU → memory</div><div class="s4-bus-line${/Data/.test(message)?' active':''}">Data bus · memory ↔ CPU</div><div class="s4-bus-line${/Control|READ/.test(message)?' active':''}">Control bus · read/write signals</div></div>${status(message)}<p>${state.halted?'END returned control to the OS.':`Current instruction fetch starts at address ${state.pc}.`}</p>`;};
 el.addEventListener('change',event=>{if(event.target.dataset.field==='speed'){speed=Number(event.target.value);if(timer){pause();timer=setInterval(next,speed);}render();}});
 el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='micro')next();if(a==='instruction'){try{state=stepInstruction(state);display=state;micro=0;message=`Whole instruction · ${state.lastDiff.join(' · ')}`;if(state.halted)pause();render();}catch(e){error(el,e.message);}}if(a==='run'){timer=setInterval(next,speed);render();}if(a==='pause'){pause();render();}if(a==='reset'){reset();render();}});
 el.addEventListener('s4-reset',pause);mount(el,render,reset);
}
function polling(el){let tick=0,cause='keyboard';const events={keyboard:['Key becomes available','Interactive input','Read and buffer the character'],disk:['Disk transfer completes','Asynchronous file I/O','Record completion and wake waiting work'],timer:['Timer interval expires','Timekeeping or scheduling','Update time or enter the scheduler'],alarm:['Temperature alarm fires','Hardware protection','Perform the required protective response'],software:['Program requests an OS service','System service','Transfer to the relevant service routine']};const reset=()=>{tick=0;cause='keyboard';};const render=()=>{const [source,application,response]=events[cause];el.innerHTML=`<h4>Polling vs interrupt timeline</h4><p>For the keyboard example, input becomes ready at time 4. Polling checks every time unit; an interrupt requests attention when the event occurs.</p>${control([button('Next time unit','next',true),button('Reset','reset')])}<div class="s4-activity-grid">${panel('Polling',`<p>${Array.from({length:Math.min(tick,4)},(_,i)=>`t${i+1}: check ${i===3?'ready':'nothing ready'}`).join(' → ')||'No checks yet.'}</p>`)}${panel('Interrupt',`<p>${tick<4?'Main program can run while no request exists.':'t4: keyboard interface raises a request; processor checks it at an instruction boundary.'}</p>`)}</div><label>Other event<select data-field="cause">${Object.keys(events).map(key=>`<option value="${key}"${key===cause?' selected':''}>${key}</option>`).join('')}</select></label>${panel('Cause → application → response',`<p><strong>Cause:</strong> ${source}<br><strong>Application:</strong> ${application}<br><strong>Service response:</strong> ${response}</p>`)}${status(`Time ${tick}: ${tick<4?'No keyboard input yet.': 'Keyboard input is ready and needs service.'}`)}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='cause'){cause=event.target.value;render();}});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='next'){tick=Math.min(4,tick+1);render();}if(a==='reset'){reset();render();}});mount(el,render,reset);}
function interrupt(el){let stage=0,priority='normal';const stages=[['Normal program','PC=330, ACC=18, IX=4, comparison=True.'],['Request pending','An I/O device requests service; the current instruction finishes first.'],['Check and accept','At the instruction boundary, enabled requests and priority are checked.'],['Save context','Save PC=330, ACC=18, IX=4 and comparison=True.'],['Transfer to ISR','PC changes to ISR address 800; original context remains saved.'],['Service event','ISR may change ACC to 65 and comparison to False while servicing I/O.'],['Restore and resume','Restore PC=330, ACC=18, IX=4, comparison=True; next fetch resumes correctly.']];const reset=()=>{stage=0;priority='normal';};const render=()=>{const [title,explanation]=stages[stage];const current={pc:stage>=4&&stage<=5?800:330,acc:stage===5?65:18,ix:4,mar:null,mdr:null,cir:null,comparison:stage===5?false:true};el.innerHTML=`<h4>Interrupt Lifecycle Simulator</h4>${control([button('Previous','previous'),button('Next stage','next',true),button('Reset','reset')])}<label>Request priority<select data-field="priority"><option value="normal"${priority==='normal'?' selected':''}>Eligible request</option><option value="lower"${priority==='lower'?' selected':''}>Lower priority while a higher one is active</option></select></label><div class="s4-activity-grid">${panel('Active processor state',registers(current))}${panel('Saved context',stage>=3?'<p>PC 330 · ACC 18 · IX 4 · comparison True</p>':'<p>Nothing saved yet.</p>')}</div>${status(`${title}: ${explanation}${priority==='lower'&&stage===2?' A lower-priority request remains pending until eligible.':''}`)}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='priority'){priority=event.target.value;render();}});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='next')stage=Math.min(stages.length-1,stage+1);if(a==='previous')stage=Math.max(0,stage-1);if(a==='reset')reset();render();});mount(el,render,reset);}
function source(el){let stage=0;const items=[['Symbolic assembly','LDD TOTAL','Readable mnemonic and a symbolic operand.'],['Resolved assembly','LDD 6','TOTAL is known to label address 6.'],['Machine word','opcode bits + operand bits','Actual bit patterns require a supplied target encoding; Cambridge does not prescribe them here.']];const reset=()=>{stage=0;};const render=()=>{const [title,code,explanation]=items[stage];el.innerHTML=`<h4>Source → resolved instruction → machine word</h4>${control([button('Previous','previous'),button('Next representation','next',true),button('Reset','reset')])}<div class="s4-activity-grid">${panel(title,`<pre><code>${escapeHtml(code)}</code></pre><p>${explanation}</p>`)}${panel('Memory context','<p>TOTAL is a data label at address 6. Memory[6] currently contains 0. Resolving the label uses 6, not 0.</p>')}</div>${status(`Representation ${stage+1} / 3. The processor executes encoded instructions, not mnemonic letters.`)}`;};el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='next')stage=Math.min(2,stage+1);if(a==='previous')stage=Math.max(0,stage-1);if(a==='reset')reset();render();});mount(el,render,reset);}
const assemblerLines=['START: LDD FIRST','ADD SECOND','STO TOTAL','END','FIRST: 18','SECOND: 24','TOTAL: 0'];
function labels(el){const built=assemble(assemblerLines);let selected='FIRST';const reset=()=>{selected='FIRST';};const render=()=>{const address=built.symbols[selected],item=built.resolved.find(row=>row.address===address);const kind=item.kind==='data'?'data location':'instruction address';el.innerHTML=`<h4>Label Map</h4><div class="s4-activity-grid">${panel('Assembly source',`<pre>${built.source.map(row=>`<button type="button" data-label="${row.label??''}" class="s4-code-line${row.label===selected?' current':''}"${row.label?'':' disabled'}>${String(row.address).padStart(3,'0')}  ${escapeHtml(row.label?`${row.label}: ${row.text}`:row.text)}</button>`).join('')}</pre>`)}${panel('Symbol table',`<div class="s4-memory-list">${Object.entries(built.symbols).map(([key,n])=>`<div class="s4-memory-row${selected===key?' changed':''}"><button type="button" data-label="${key}">${key}</button><span>${n}</span></div>`).join('')}</div>`)}</div>${status(`${selected} names ${kind} ${address}. ${item.kind==='data'?`Memory[${address}] contains ${item.value}; the symbol table still stores ${address}.`:'A jump may use this instruction address as its target.'}`)}`;};el.addEventListener('click',event=>{const label=event.target.closest('[data-label]')?.dataset.label;if(label&&Object.hasOwn(built.symbols,label)){selected=label;render();}});mount(el,render,reset);}
function assemblerActivity(el){let example='forward',pass=1,index=0;const lines=()=>example==='missing'?['START: LDD MISSING','END','VALUE: 18']:example==='duplicate'?['START: LDD FIRST','FIRST: 18','FIRST: 24']:assemblerLines;const reset=()=>{example='forward';pass=1;index=0;};const render=()=>{const built=assemble(lines());const visible=pass===1?built.source.slice(0,index):built.resolved.slice(0,index);const symbols=pass===1?Object.fromEntries(visible.filter(row=>row.label).map(row=>[row.label,row.address])):built.symbols;el.innerHTML=`<h4>Two-Pass Assembler</h4><label>Scenario<select data-field="example"><option value="forward"${example==='forward'?' selected':''}>Forward reference</option><option value="missing"${example==='missing'?' selected':''}>Undefined label</option><option value="duplicate"${example==='duplicate'?' selected':''}>Duplicate label</option></select></label>${control([button('Next line','next',true),button('Switch pass','pass'),button('Reset','reset')])}<div class="s4-activity-grid">${panel(`Pass ${pass} · source`, `<pre>${built.source.map((row,i)=>`<span class="s4-code-line${i===index-1?' current':''}">${String(row.address).padStart(3,'0')}  ${escapeHtml(row.label?`${row.label}: ${row.text}`:row.text)}</span>`).join('')}</pre>`)}${panel('Location counter and symbol table',`<p>Next address: ${pass===1?(built.source[0]?.address??0)+index:built.source.length}</p><div class="s4-memory-list">${Object.entries(symbols).map(([key,n])=>`<div class="s4-memory-row"><span>${key}</span><span>${n}</span></div>`).join('')||'<p>No labels recorded yet.</p>'}</div>`)}</div>${pass===2?panel('Resolved output · no invented opcode bits',`<pre>${visible.map(row=>`${String(row.address).padStart(3,'0')}  ${escapeHtml(row.resolved??row.value)}`).join('\n')}</pre>`):''}${status(built.errors.length?built.errors.join(' '):pass===1?index===built.source.length?'Pass one complete. All label addresses are now known.':'Pass one records each label and advances one location per item.':index===built.resolved.length?'Pass two resolves the forward references and emits the instruction/data image.':'Pass two uses the completed symbol table to resolve each operand.')}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='example'){example=event.target.value;pass=1;index=0;render();}});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset')reset();if(a==='next')index=Math.min(lines().length,index+1);if(a==='pass'){pass=pass===1?2:1;index=0;}if(a)render();});mount(el,render,reset);}
function addressing(el){let mode='indirect',memory100=150,memory150=7,ix=2,revealed=false;const reset=()=>{mode='indirect';memory100=150;memory150=7;ix=2;revealed=false;};const render=()=>{const memory={100:memory100,150:memory150,200:3,202:42};const examples={immediate:'#7',direct:'150',indirect:'100',indexed:'200',relative:'-3'};let result,errorMessage='';try{result=resolveAddress(mode,examples[mode],memory,ix,40);}catch(e){errorMessage=e.message;}el.innerHTML=`<h4>Addressing Mode Explorer</h4><label>Mode<select data-field="mode">${['immediate','direct','indirect','indexed','relative'].map(v=>`<option${v===mode?' selected':''}>${v}</option>`).join('')}</select></label><label>Memory[100]<input data-field="memory100" type="number" value="${memory100}"></label><label>Memory[150]<input data-field="memory150" type="number" value="${memory150}"></label><label>IX<input data-field="ix" type="number" value="${ix}"></label><div class="s4-activity-grid">${panel('Given',`<p>Operand ${examples[mode]} · PC base 40</p>${memoryHtml(memory)}`)}${panel('Path',errorMessage?`<p>${escapeHtml(errorMessage)}</p>`:revealed?`<ol>${result.path.map(part=>`<li>${escapeHtml(part)}</li>`).join('')}</ol><p>${mode==='relative'?`Effective address ${result.address}; no invented opcode or memory read.`:`${result.address===null?'No data-memory address.':`Effective address ${result.address}.`} Value ${result.value}.`}</p>`:'<p>Predict the number of memory dereferences and the final value, then reveal the path.</p>')}</div>${control([button('Reveal path','reveal',true),button('Reset','reset')])}${status(errorMessage||`${mode==='relative'?'Relative is a conceptual address calculation here.':'Changing the supplied memory or IX changes the result.'}`)}`;};el.addEventListener('change',event=>{const field=event.target.dataset.field;if(!field)return;if(field==='mode')mode=event.target.value;else{const n=Number(event.target.value);if(field==='memory100')memory100=n;if(field==='memory150')memory150=n;if(field==='ix')ix=n;}revealed=false;render();});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reveal')revealed=true;if(a==='reset')reset();if(a)render();});mount(el,render,reset);}
const instructionExample={LDM:'LDM #7',LDD:'LDD 5',LDI:'LDI 100',LDX:'LDX 5',LDR:'LDR #3',MOV:'MOV IX',STO:'STO 20',ADD:'ADD #2',SUB:'SUB 5',INC:'INC ACC',DEC:'DEC IX',JMP:'JMP 2',CMP:'CMP #18',CMI:'CMI 100',JPE:'JPE 2',JPN:'JPN 2',IN:'IN',OUT:'OUT',END:'END',AND:'AND B00001111',OR:'OR B00000100',XOR:'XOR B00000100',LSL:'LSL #1',LSR:'LSR #1'};
function instructions(el){let op='LDI',comparison=true,executed=null;const reset=()=>{op='LDI';comparison=true;executed=null;};const start=()=>{const s=initialState({origin:0,acc:op==='OUT'?65:18,ix:2,lines:[instructionExample[op],'END','END'],memory:{5:24,7:11,20:0,100:150,150:7},input:'A'});s.comparison=comparison;return s;};const render=()=>{const state=executed??start(),meta=INSTRUCTIONS[op];el.innerHTML=`<h4>Instruction State Explorer</h4><label>Official example instruction<select data-field="op">${Object.keys(INSTRUCTIONS).map(key=>`<option${op===key?' selected':''}>${key}</option>`).join('')}</select></label><label>Previous comparison<select data-field="comparison"><option value="true"${comparison?' selected':''}>True</option><option value="false"${comparison?'':' selected'}>False</option></select></label><p><code>${instructionExample[op]}</code> · ${meta.group} · ${meta.effect}</p>${control([button('Execute one instruction','execute',true),button('Reset state','reset')])}<div class="s4-activity-grid">${panel('Processor state',registers(state))}${panel('Relevant memory and output',`${memoryHtml(Object.fromEntries([5,7,20,100,150].map(n=>[n,state.memory[n]])))}<p>Output: ${escapeHtml(state.output)||'—'}</p>`)}</div>${status(executed?executed.lastDiff.join(' · '):'Predict which state element will change. CMP/CMI do not change ACC.')}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='op')op=event.target.value;if(event.target.dataset.field==='comparison')comparison=event.target.value==='true';executed=null;render();});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset')executed=null;if(a==='execute'){try{executed=stepInstruction(start());}catch(e){error(el,e.message);return;}}if(a)render();});mount(el,render,reset);}
const loopProgram={origin:20,acc:0,ix:0,memory:{90:67},input:'',lines:['LDM #2','LOOP: DEC ACC','CMP #0','JPN LOOP','LDD 90','OUT','END']};
function traceTable(rows){return `<div class="s4-trace-wrap" role="region" aria-label="Executed instruction trace" tabindex="0"><table class="s4-trace"><thead><tr><th>Address</th><th>Executed instruction</th><th>ACC</th><th>IX</th><th>Next PC</th><th>Comparison</th><th>Memory / output change</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${row.address}</td><td>${escapeHtml(row.instruction)}</td><td>${row.acc}</td><td>${row.ix}</td><td>${row.nextPC??'OS'}</td><td>${row.comparison===null?'—':row.comparison}</td><td>${escapeHtml(row.diff.filter(x=>x.startsWith('Memory')||x.startsWith('OUTPUT')).join('; ')||'—')}</td></tr>`).join('')}</tbody></table></div><p class="s4-scroll-cue">Swipe horizontally to inspect every trace column.</p>`;}
function traceActivity(el,complete=false){const completeProgram={origin:30,acc:0,ix:0,memory:{},input:'A',lines:['IN','CMP #65','JPE SAME','LDM #63','JMP SEND','SAME: ADD #1','SEND: OUT','END']};let input='A',state,message='Predict ACC and next PC before running the current instruction.';const make=()=>initialState(complete?{...completeProgram,input}:loopProgram);const reset=()=>{input='A';state=make();message='Predict ACC and next PC before running the current instruction.';};reset();const render=()=>{const source=complete?{...completeProgram,input}:loopProgram;const built=assemble(source.lines,source.origin);el.innerHTML=`<h4>${complete?'Complete Program Challenge':'Program Trace Runner'}</h4>${complete?`<label>Input character<select data-field="input"><option${input==='A'?' selected':''}>A</option><option${input==='B'?' selected':''}>B</option></select></label>`:''}<div class="s4-activity-grid">${panel('Source · current instruction highlighted',`<pre>${built.source.map(row=>`<span class="s4-code-line${row.address===state.pc?' current':''}">${row.address}  ${escapeHtml(row.label?`${row.label}: ${row.text}`:row.text)}</span>`).join('')}</pre>`)}${panel('Processor and output',`${registers(state)}<p>Output: ${escapeHtml(state.output)||'—'}</p>`)}</div><label>Predict ACC<input data-field="predictAcc" type="number" placeholder="Optional"></label><label>Predict next PC<input data-field="predictPc" type="number" placeholder="Optional"></label>${control([button('Run one instruction','step',true),button('Reset','reset')])}${status(message)}<h5>Executed instructions only</h5>${traceTable(state.trace)}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='input'){input=event.target.value;state=make();render();}});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset'){reset();render();return;}if(a!=='step'||state.halted)return;const accText=el.querySelector('[data-field=predictAcc]').value,pcText=el.querySelector('[data-field=predictPc]').value;try{state=stepInstruction(state);const feedback=[];if(accText)feedback.push(Number(accText)===state.acc?'ACC prediction correct.':`ACC is ${state.acc}.`);if(pcText)feedback.push(Number(pcText)===state.pc?'PC prediction correct.':`Next PC is ${state.pc??'OS'}.`);message=`${feedback.join(' ')} ${state.lastDiff.join(' · ')}${state.halted?' END returned control to the OS.':''}`;render();}catch(e){error(el,e.message);}});mount(el,render,reset);}
function shift(el){let value='10110001',kind='logical',direction='right',amount=1,shown=0,result=null;const reset=()=>{value='10110001';kind='logical';direction='right';amount=1;shown=0;result=null;};const render=()=>{let parsed=null,issue='';try{if(!/^[01]{8}$/.test(value))throw new Error('Enter exactly eight binary digits.');parsed=parseInt(value,2);result=shiftBits(parsed,kind,direction,amount);}catch(e){issue=e.message;result=null;}const current=result?.states[Math.min(shown,result.states.length-1)]??parsed;el.innerHTML=`<h4>Binary Shift Lab · fixed 8-bit model</h4><label>Starting byte<input data-field="value" inputmode="numeric" maxlength="8" value="${escapeHtml(value)}"></label><label>Shift type<select data-field="kind">${['logical','arithmetic','cyclic'].map(v=>`<option${v===kind?' selected':''}>${v}</option>`).join('')}</select></label><label>Direction<select data-field="direction"><option${direction==='left'?' selected':''}>left</option><option${direction==='right'?' selected':''}>right</option></select></label><label>Places<select data-field="amount">${[1,2,3,4].map(n=>`<option${amount===n?' selected':''}>${n}</option>`).join('')}</select></label>${control([button('Next bit movement','next',true),button('Reset','reset')])}${current!==null?binStrip(current,shown?result.states[shown-1]:null):''}${status(issue||`Movement ${shown}/${amount}. ${kind==='arithmetic'&&direction==='right'?'Arithmetic right repeats the original sign bit on the left.':kind==='cyclic'?'Cyclic moves the displaced bit to the opposite end.':'Logical fills vacated positions with zero.'}`)}<p>Cambridge example opcodes are LSL and LSR. Arithmetic and cyclic shifts here are concepts, not invented opcodes.</p>`;};el.addEventListener('change',event=>{const f=event.target.dataset.field;if(!f)return;if(f==='value')value=event.target.value;if(f==='kind')kind=event.target.value;if(f==='direction')direction=event.target.value;if(f==='amount')amount=Number(event.target.value);shown=0;render();});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='next')shown=Math.min(amount,shown+1);if(a==='reset')reset();if(a)render();});mount(el,render,reset);}
function mask(el){let value='10101100',maskValue='00001111',operation='AND',bit=2,task='test';const reset=()=>{value='10101100';maskValue='00001111';operation='AND';bit=2;task='test';};const render=()=>{const valid=/^[01]{8}$/.test(value)&&/^[01]{8}$/.test(maskValue);const v=valid?parseInt(value,2):null,m=valid?parseInt(maskValue,2):null;const result=valid?applyMask(v,m,operation):null;el.innerHTML=`<h4>Bit Mask Lab</h4><label>ACC byte<input data-field="value" inputmode="numeric" maxlength="8" value="${escapeHtml(value)}"></label><label>Mask byte<input data-field="maskValue" inputmode="numeric" maxlength="8" value="${escapeHtml(maskValue)}"></label><label>Operation<select data-field="operation">${['AND','OR','XOR'].map(x=>`<option${x===operation?' selected':''}>${x}</option>`).join('')}</select></label>${valid?`<div class="s4-bit-equation"><span>${value}</span><span>${operation} ${maskValue}</span><span>= ${bits(result)}</span></div>${binStrip(result,v)}`:''}${status(valid?'Each output bit is calculated from the two bits in its column.':'Enter exactly eight binary digits in both fields.')}<h5>Mask Builder</h5><label>Task<select data-field="task">${['test','set','toggle','clear'].map(x=>`<option${x===task?' selected':''}>${x}</option>`).join('')}</select></label><label>Bit position<select data-field="bit">${Array.from({length:8},(_,n)=>`<option${n===bit?' selected':''}>${n}</option>`).join('')}</select></label>${control([button('Build mask','build',true),button('Reset','reset')])}`;};el.addEventListener('change',event=>{const f=event.target.dataset.field;if(!f)return;if(f==='value')value=event.target.value;if(f==='maskValue')maskValue=event.target.value;if(f==='operation')operation=event.target.value;if(f==='bit')bit=Number(event.target.value);if(f==='task')task=event.target.value;render();});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset')reset();if(a==='build'){maskValue=bits(task==='clear'?255^(1<<bit):1<<bit);operation=task==='test'||task==='clear'?'AND':task==='set'?'OR':'XOR';}if(a)render();});mount(el,render,reset);}
function device(el){let byte=17,state,message='Test bit 4, branch on the comparison, and preserve unrelated bits.';const program=value=>({origin:100,acc:0,ix:0,memory:{900:value},input:'',lines:['LDD 900','AND B00010000','CMP #0','JPE DONE','LDD 900','OR B00000100','STO 900','DONE: END']});const reset=()=>{byte=17;state=initialState(program(byte));message='Test bit 4, branch on the comparison, and preserve unrelated bits.';};reset();const render=()=>{const source=assemble(program(byte).lines,100);el.innerHTML=`<h4>Device Register Challenge</h4><label>Initial interface byte<select data-field="byte">${[[17,'00010001 · ready'],[1,'00000001 · not ready'],[21,'00010101 · already enabled']].map(([v,t])=>`<option value="${v}"${v===byte?' selected':''}>${t}</option>`).join('')}</select></label><div class="s4-activity-grid">${panel('Current instruction',`<pre>${source.source.map(row=>`<span class="s4-code-line${row.address===state.pc?' current':''}">${row.address}  ${escapeHtml(row.label?`${row.label}: ${row.text}`:row.text)}</span>`).join('')}</pre>`)}${panel('Device byte and processor',`${binStrip(state.memory[900],byte)}${registers(state)}`)}</div>${control([button('Next instruction','step',true),button('Reset','reset')])}${status(message)}${traceTable(state.trace)}`;};el.addEventListener('change',event=>{if(event.target.dataset.field==='byte'){byte=Number(event.target.value);state=initialState(program(byte));render();}});el.addEventListener('click',event=>{const a=event.target.closest('[data-action]')?.dataset.action;if(a==='reset'){reset();render();return;}if(a==='step'&&!state.halted){try{state=stepInstruction(state);message=`${state.lastDiff.join(' · ')}${state.halted?' Program ended.':' Predict the next path before stepping.'}`;render();}catch(e){error(el,e.message);}}});mount(el,render,reset);}

const activities={stored,components,registers:registersActivity,bus,width,performance,cache,ports,notation,fetch,polling,interrupt,source,labels,assembler:assemblerActivity,addressing,instructions,trace:el=>traceActivity(el),complete:el=>traceActivity(el,true),shift,mask,device};
for(const el of document.querySelectorAll('.s4-activity')){try{activities[el.dataset.activity]?.(el);}catch(e){el.innerHTML=`<p class="s4-status s4-error" role="alert">${escapeHtml(e.message)}</p>`;}}
if(root){
 const blocks=[...root.querySelectorAll('.s4-block')],levels=blocks.map(()=>0);let active=0,mode='teaching';
 function closeAnswers(scope=root){scope.querySelectorAll('details[open]').forEach(detail=>{if(!detail.classList.contains('s4-lesson-info'))detail.open=false;});}
 function showBlock(index){active=Math.max(0,Math.min(blocks.length-1,index));blocks.forEach((block,i)=>{block.hidden=i!==active;block.querySelectorAll('[data-reveal]').forEach(phase=>{phase.hidden=Number(phase.dataset.reveal)>levels[i];});});root.querySelectorAll('[data-select-block]').forEach((button,i)=>button.setAttribute('aria-current',i===active?'step':'false'));root.querySelector('[data-block-progress]').textContent=`${active+1} / ${blocks.length} knowledge blocks`;root.querySelector('.s4-exam-challenge').hidden=active!==blocks.length-1;root.querySelector('[data-previous-block]').disabled=active===0;root.querySelector('[data-next-block]').disabled=active===blocks.length-1;}
 function setMode(next){mode=next;root.querySelector('[data-teaching]').hidden=mode!=='teaching';root.querySelector('[data-revision]').hidden=mode!=='revision';root.querySelectorAll('[data-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.mode===mode)));showBlock(active);}
 root.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target)return;
   if(target.dataset.s4Print){const details=[...root.querySelectorAll('.s4-teaching details,.s4-revision details')];const opened=details.map(d=>d.open);document.body.dataset.s4Print=target.dataset.s4Print;details.forEach(d=>{d.open=target.dataset.s4Print==='answers';});try{window.print();}finally{details.forEach((d,i)=>{d.open=opened[i];});delete document.body.dataset.s4Print;}return;}
   if(target.dataset.mode){setMode(target.dataset.mode);return;}
   if(target.dataset.selectBlock!==undefined){showBlock(Number(target.dataset.selectBlock));return;}
   if(target.dataset.jumpBlock!==undefined){event.preventDefault();setMode('teaching');showBlock(Number(target.dataset.jumpBlock));blocks[active].scrollIntoView({block:'start'});return;}
   if(target.hasAttribute('data-next-block')){showBlock(active+1);blocks[active].scrollIntoView({block:'start'});return;}
   if(target.hasAttribute('data-previous-block')){showBlock(active-1);blocks[active].scrollIntoView({block:'start'});return;}
   if(target.hasAttribute('data-next-reveal'))levels[active]=Math.min(3,levels[active]+1);
   if(target.hasAttribute('data-previous-step'))levels[active]=Math.max(0,levels[active]-1);
   if(target.hasAttribute('data-show-explanation'))levels[active]=Math.max(1,levels[active]);
   if(target.hasAttribute('data-show-answers')){levels[active]=Math.max(2,levels[active]);blocks[active].querySelectorAll('.s4-immediate details,.s4-transfer details').forEach(d=>d.open=true);}
   if(target.hasAttribute('data-hide-answers'))closeAnswers(blocks[active]);
   if(target.hasAttribute('data-reveal-all')){levels[active]=3;blocks[active].querySelectorAll('.s4-immediate details,.s4-transfer details').forEach(d=>d.open=true);}
   if(target.hasAttribute('data-reset-activity'))blocks[active].querySelectorAll('.s4-activity').forEach(el=>el.dispatchEvent(new Event('s4-reset')));
   if(target.hasAttribute('data-reset-lesson')){levels.fill(0);active=0;closeAnswers();root.querySelectorAll('.s4-activity').forEach(el=>el.dispatchEvent(new Event('s4-reset')));setMode('teaching');}
   if(target.dataset.recallMode){const reveal=target.dataset.recallMode==='reveal';root.querySelectorAll('.s4-recall-card').forEach(card=>card.open=reveal);root.querySelectorAll('[data-recall-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button===target)));}
   showBlock(active);
 });
 showBlock(0);
}

})();
